import urllib.request,urllib.error,json
urls=['/saas/console/login','/saas/console/assets/css/app.css','/saas/console/assets/js/app.js','/saas/console/_core/Bootstrap.php','/saas/console/database/Seed.php']
output=[]
for path in urls:
 try:
  req=urllib.request.Request('https://app.ontrackegy.com'+path,headers={'User-Agent':'OnTrack-SaaS-Health/2.0'})
  with urllib.request.urlopen(req,timeout=5) as r:
   body=r.read(12000);output.append({'path':path,'status':r.status,'length':len(body),'type':r.headers.get('Content-Type'),'has_login':b'password' in body})
 except urllib.error.HTTPError as e:output.append({'path':path,'status':e.code})
 except Exception as e:output.append({'path':path,'error':type(e).__name__})
print(json.dumps(output))
